import Dashboard from "./Components/Dashboard";
import MovieList from "./Components/MovieList";
import Movies from "./Components/Movies";
import Navbar from "./Components/Navbar";

function App() {
  let movieList = [{
    id: 1,
    poster: "https://image.tmdb.org/t/p/w500/8UlWHLMpgZm9bx6QYh0NFoq67TZ.jpg",
    title: "Wonder Woman",
    genre: "Sci-Fi",
    year: 2010
  }, {
    id: 2,
    poster: "https://image.tmdb.org/t/p/w500/qJ2tW6WMUDux911r6m7haRef0WH.jpg",
    title: "The Dark Knight",
    genre: "Action",
    year: 2008
  }, {
    id: 3,
    poster: "https://mir-s3-cdn-cf.behance.net/project_modules/hd/297acd129204217.616629e21fe76.png",
    title: "Interstellar",
    genre: "Sci-Fi",
    year: 2014
  },
  {
    id: 4,
    poster: "https://m.media-amazon.com/images/I/71DwIcSgFcS.jpg",
    title: "Inception",
    genre: "Sci-Fi",
    year: 2010
  },
  {
    id: 5,
    poster: "https://cdn.europosters.eu/image/1300/104636.jpg",
    title: "The Matrix",
    genre: "Sci-Fi",
    year: 1999
  },
  {
    id: 6,
    poster: "https://artofthemovies.co.uk/cdn/shop/files/IMG_9379_259d5a58-fdf4-4338-9f78-eb0534a60a3d_720x@2x.jpg?v=1713453949",
    title: "The Avengers",
    genre: "Action",
    year: 2012
  },
  {
    id: 7,
    poster: "https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcT1-9ii1HTFYQvUmAK5krxBj2-ux8zLW8OTUg&s",
    title: "Spiderman",
    genre: "Action",
    year: 2002
  },{
    id: 8,
    poster: "https://upload.wikimedia.org/wikipedia/en/thumb/4/4e/Spider-Man_2_poster.jpg/250px-Spider-Man_2_poster.jpg",
    title: "Spiderman 2",
    genre: "Action",
    year: 2004
  }];
  return (
    <>
      <Navbar/>
      <Dashboard>
        <Movies>
          {movieList.map((movie)=><MovieList movie={movie}/>)}
        </Movies>
      </Dashboard>
    </>
  );
}

export default App;
